import { sparql as baseSparql } from '@codemirror/legacy-modes/mode/sparql';
import { tags } from '@lezer/highlight';
/**
 * CodeMirror 6 language for SPARQL-Generate.
 *
 * A `StreamParser` that DELEGATES to the SPARQL mode of
 * `@codemirror/legacy-modes` (`mode/sparql`), token for token, everything
 * that is SPARQL, and handles itself only what `src/lexicon.js` describes:
 * the SPARQL-Generate keywords, the `fun:`/`iter:` library names, the
 * expression nodes `?{ … }` / `${ … }`, and the expressions embedded in IRIs
 * and string literals. A plain SPARQL 1.1 query therefore gets exactly the
 * tokens of the SPARQL mode (parity test, `npm test`).
 *
 * This is the one engine with a real STATE: a stack of frames (string, IRI,
 * expression) nests to any depth — `"{ CONCAT(?a, "-{?b}-") }"` — where the
 * regular-expression engines must flatten.
 *
 * One difference with the SPARQL mode is deliberate: the SPARQL mode does not
 * know long strings (`"""…"""`, `'''…'''`) and reads them as runs of short
 * ones; this parser reads them whole, since a template string is often long.
 * On a long string without inner quotes both give the same tokens.
 *
 * usage (ESM, what the playground does):
 *     import { StreamLanguage } from '@codemirror/language';
 *     import { sparqlGenerate } from 'highlight-sparql-generate/codemirror.mjs';
 *     const language = StreamLanguage.define(sparqlGenerate);
 *
 * usage (CommonJS):
 *     const { build } = require('highlight-sparql-generate/codemirror');
 *     const { tags } = require('@lezer/highlight');
 *     const language = StreamLanguage.define(build({ tags }));
 */

// The lexicon (src/lexicon.js), inlined.
const L = {
    "P": {
        "generateKeywords": "(?<![\\w?$:.\\-])(?:generate|template|perform|function|iterator|source|accept|box|format|before|after|list|expressions|pragma)(?![\\w\\-:])",
        "reusedKeywords": "(?<![\\w?$:.\\-])(?:group)(?![\\w\\-:])",
        "libraryName": "(?<![\\w?$:.\\-])(?:fun|iter):[A-Za-z_](?:[\\w.\\-]*[\\w\\-])?",
        "xexprOpen": "[?$]\\{",
        "iriChar": "[^<>\"{}|^`\\\\\\x00-\\x20]",
        "xiriStart": "<(?=[^<>\"{}|^`\\\\\\x00-\\x20]*\\{)",
        "echar": "\\\\[tbnrf\"'\\\\{}]",
        "interpFlat": "\\{(?:[^{}\"'\\n]|\"(?:[^\"\\\\\\n]|\\\\.)*\"|'(?:[^'\\\\\\n]|\\\\.)*'|\\{(?:[^{}\"'\\n]|\"(?:[^\"\\\\\\n]|\\\\.)*\"|'(?:[^'\\\\\\n]|\\\\.)*')*\\})*\\}"
    }
};

/** Token names this parser emits on its own. `keyword`, `builtin`, `string`
 *  and `atom` are those the SPARQL mode gives to a keyword, a built-in, a
 *  string and an IRI; only the interpolation braces need a name of their
 *  own, mapped to a tag by `tokenTable`. */
const TOKEN = {
    'keyword.generate': 'keyword',
    'function.library': 'builtin',
    'string': 'string',
    'iri': 'atom',
    'interp.punct': 'sgInterpolation',
};

/** Lezer tags for the token names that are not standard ones. */
function tokenTable(tags) {
    return { sgInterpolation: [tags.special(tags.brace), tags.escape] };
}

const sticky = (source, flags = '') => new RegExp(source, 'y' + flags);

const RE = {
    keyword: sticky(L.P.generateKeywords, 'i'),
    library: sticky(L.P.libraryName),
    xexprOpen: sticky(L.P.xexprOpen),
    xiriStart: sticky(L.P.xiriStart),
    iriChars: sticky(L.P.iriChar + '+'),
};

/** Match a sticky regex at the stream position, against the WHOLE line (so
 *  that lookbehinds see what precedes). Consumes on success. */
function matchAt(stream, re) {
    re.lastIndex = stream.pos;
    const m = re.exec(stream.string);
    if (!m || m.index !== stream.pos) return null;
    stream.pos += m[0].length;
    return m[0];
}

/** Does a string opened by `quote` at `from` hold an embedded expression
 *  before it closes on this line? (A short string cannot span lines.) */
function shortStringHasInterp(line, from, quote) {
    for (let i = from + 1; i < line.length; i++) {
        const c = line[i];
        if (c === '\\') { i++; continue; }
        if (c === quote) return false;
        if (c === '{') return true;
    }
    return false;
}

/** Build the stream parser. `sparql` defaults to the SPARQL mode of
 *  `@codemirror/legacy-modes`; `tags` (from `@lezer/highlight`) adds the
 *  `tokenTable` for the interpolation braces. */
function build(options = {}) {
    const sparql = options.sparql || baseSparql;
    // The SPARQL mode's "between tokens" tokenizer: a base state whose
    // `tokenize` is this one is not inside one of its string literals.
    const BASE_IDLE = sparql.startState(2).tokenize;

    const parser = {
        name: 'sparql-generate',

        startState(indentUnit) {
            return { base: sparql.startState(indentUnit), stack: [] };
        },

        copyState(state) {
            return {
                base: sparql.copyState ? sparql.copyState(state.base)
                    : Object.assign({}, state.base),
                stack: state.stack.map((f) => Object.assign({}, f)),
            };
        },

        token(stream, state) {
            const top = state.stack[state.stack.length - 1];
            if (top && top.kind === 'string') return inString(stream, state, top);
            if (top && top.kind === 'iri') return inIri(stream, state);
            return inCode(stream, state, top);
        },

        blankLine(state, indentUnit) {
            if (sparql.blankLine) sparql.blankLine(state.base, indentUnit);
        },

        indent(state, textAfter, cx) {
            if (state.stack.length) return null;
            return sparql.indent ? sparql.indent(state.base, textAfter, cx) : null;
        },

        languageData: sparql.languageData,
    };
    if (options.tags) parser.tokenTable = tokenTable(options.tags);

    /** SPARQL code: top level, or the body of an embedded expression. */
    function inCode(stream, state, frame) {
        const idle = state.base.tokenize === BASE_IDLE;
        if (idle && !stream.match(/^\s/, false)) {
            const ch = stream.peek();
            // The end of an embedded expression, or a group inside it.
            if (frame && frame.kind === 'expr') {
                if (ch === '}' && frame.depth === 0) {
                    stream.next();
                    state.stack.pop();
                    return TOKEN['interp.punct'];
                }
                if (ch === '{') frame.depth++;
                else if (ch === '}') frame.depth--;
            }
            if (matchAt(stream, RE.xexprOpen)) {
                state.stack.push({ kind: 'expr', depth: 0 });
                return TOKEN['interp.punct'];
            }
            if (ch === '<' && matchAt(stream, RE.xiriStart)) {
                // consumed `<`; the IRI characters come next
                state.stack.push({ kind: 'iri' });
                return TOKEN.iri;
            }
            if (ch === '"' || ch === "'") {
                const long = stream.match(ch + ch + ch, false);
                if (long || shortStringHasInterp(stream.string, stream.pos, ch)) {
                    stream.pos += long ? 3 : 1;
                    state.stack.push({ kind: 'string', quote: long ? ch + ch + ch : ch });
                    return TOKEN.string;
                }
            }
            if (matchAt(stream, RE.keyword)) return TOKEN['keyword.generate'];
            if (matchAt(stream, RE.library)) return TOKEN['function.library'];
        }
        return sparql.token(stream, state.base);
    }

    /** The literal part of a string with embedded expressions. */
    function inString(stream, state, frame) {
        const q = frame.quote;
        if (stream.match(q)) {
            state.stack.pop();
            return TOKEN.string;
        }
        if (stream.peek() === '{') {
            stream.next();
            state.stack.push({ kind: 'expr', depth: 0 });
            return TOKEN['interp.punct'];
        }
        while (!stream.eol()) {
            const c = stream.peek();
            if (c === '{' || stream.match(q, false)) break;
            stream.next();
            if (c === '\\') stream.next();
        }
        if (stream.eol() && q.length === 1) state.stack.pop();   // unterminated
        return TOKEN.string;
    }

    /** The literal part of an IRI with embedded expressions. */
    function inIri(stream, state) {
        if (matchAt(stream, RE.iriChars)) return TOKEN.iri;
        const c = stream.next();
        if (c === '{') {
            state.stack.push({ kind: 'expr', depth: 0 });
            return TOKEN['interp.punct'];
        }
        state.stack.pop();          // `>`, or anything that ends the IRI
        return TOKEN.iri;
    }

    return parser;
}

/** The language, ready for `StreamLanguage.define`. */
const sparqlGenerate = build({ tags });

export { build, tokenTable, TOKEN, sparqlGenerate };
export default sparqlGenerate;
